/* From Uiverse.io by sammykINC - Tags: button, menu, animated, settings */
/* works only on a dark background with these paremeters*/

.__UIV_SCOPE__ .button {
  border-radius: 50%;
  border: none;
  display: flex;
  place-items: center;
  background-color: transparent;
  cursor: pointer;
}

.__UIV_SCOPE__ .button > svg {
  border-radius: inherit;
  padding: 0.5rem;
  fill: #fff;
 /* SVG color */
  width: 38px;
 /* default width 32px */
  height: 38px;
 /* default height 32px */
}

.__UIV_SCOPE__ .button > svg:active {
  background-color: rgba(65, 65, 65, 0.5);
}

.__UIV_SCOPE__ .button > svg:not(:active) {
  animation: fadeOut 0.9s;
}

@keyframes fadeOut {
  0% {
    outline: 1px solid rgba(90, 90, 90, 0.5);
 /* If you use border it will take space inside and slightly move the SVG */
  }

  100% {
    background-color: transparent;
  }
}
